const net = require('net');
const crypto = require('crypto');

class CircuitBreaker {
  constructor(threshold, resetTimeout) {
    this.threshold = threshold;
    this.resetTimeout = resetTimeout;
    this.failureCount = 0;
    this.successCount = 0;
    this.state = 'CLOSED';
    this.lastFailureTime = 0;
    this.windowStart = Date.now();
    this.windowSize = 60000;
  }

  recordSuccess() {
    if (this.state === 'HALF_OPEN') {
      this.state = 'CLOSED';
      this.failureCount = 0;
    }
    this.successCount++;
  }

  recordFailure() {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this.failureCount >= this.threshold) {
      this.state = 'OPEN';
    }
  }

  canExecute() {
    if (this.state === 'CLOSED') return true;
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime > this.resetTimeout) {
        this.state = 'HALF_OPEN';
        return true;
      }
      return false;
    }
    return true;
  }

  getHealthScore() {
    const total = this.successCount + this.failureCount;
    if (total === 0) return 100;
    const elapsed = Date.now() - this.windowStart;
    const windowFactor = Math.min(elapsed / this.windowSize, 1.0);
    const rawScore = ((this.successCount - this.failureCount) / total) * 100;
    return Math.floor(rawScore * windowFactor);
  }
}

class RateLimiter {
  constructor(maxTokens, refillRate) {
    this.maxTokens = maxTokens;
    this.tokens = maxTokens;
    this.refillRate = refillRate;
    this.lastRefill = Date.now();
  }

  refill() {
    const now = Date.now();
    const elapsed = now - this.lastRefill;
    const tokensToAdd = Math.floor(elapsed / 1000) * this.refillRate;
    this.tokens = Math.min(this.maxTokens, this.tokens + tokensToAdd);
    this.lastRefill = now;
  }

  consume(count) {
    this.refill();
    if (this.tokens < count) {
      return false;
    }
    this.tokens -= count;
    return true;
  }

  getRemaining() {
    this.refill();
    return this.tokens;
  }
}

class MessageBuffer {
  constructor(capacity) {
    this.capacity = capacity;
    this.buffer = new ArrayBuffer(capacity);
    this.view = new DataView(this.buffer);
    this.writeOffset = 0;
    this.messageCount = 0;
  }

  computeSlotSize(msgLength) {
    const headerSize = 8;
    return headerSize + msgLength;
  }

  availableSpace() {
    return this.capacity - this.writeOffset;
  }

  writeMessage(userId, message) {
    const msgBytes = Buffer.from(message, 'utf8');
    const slotSize = this.computeSlotSize(msgBytes.length);

    if (slotSize > this.availableSpace()) {
      this.compact();
      if (slotSize > this.availableSpace()) {
        return false;
      }
    }

    this.view.setUint16(this.writeOffset, userId, true);
    this.view.setUint16(this.writeOffset + 2, msgBytes.length, true);
    this.view.setUint32(this.writeOffset + 4, Date.now() & 0xFFFFFFFF, true);

    for (let i = 0; i < msgBytes.length; i++) {
      this.view.setUint8(this.writeOffset + 8 + i, msgBytes[i]);
    }

    this.writeOffset += slotSize;
    this.messageCount++;
    return true;
  }

  compact() {
    this.writeOffset = 0;
    this.messageCount = 0;
  }
}

class ChatServer {
  constructor(port) {
    this.port = port;
    this.clients = new Map();
    this.nextClientId = 1;
    this.circuitBreaker = new CircuitBreaker(5, 30000);
    this.rateLimiters = new Map();
    this.messageBuffer = new MessageBuffer(65536);
    this.messageHistory = [];
    this.maxHistoryPerUser = 100;
  }

  start() {
    this.server = net.createServer((socket) => this.handleConnection(socket));
    this.server.listen(this.port, () => {
      console.log(`Chat server listening on port ${this.port}`);
    });
  }

  handleConnection(socket) {
    if (!this.circuitBreaker.canExecute()) {
      socket.write('SERVER_OVERLOADED\n');
      socket.destroy();
      return;
    }

    const clientId = this.nextClientId++;
    this.clients.set(clientId, { socket, joinedAt: Date.now(), msgCount: 0 });
    this.rateLimiters.set(clientId, new RateLimiter(20, 5));

    socket.on('data', (data) => this.handleMessage(clientId, data));
    socket.on('close', () => this.handleDisconnect(clientId));
    socket.on('error', () => this.handleDisconnect(clientId));

    this.circuitBreaker.recordSuccess();
    socket.write(`WELCOME ${clientId}\n`);
  }

  handleMessage(clientId, data) {
    const client = this.clients.get(clientId);
    if (!client) return;

    const limiter = this.rateLimiters.get(clientId);
    const message = data.toString('utf8').trim();

    if (message.length === 0 || message.length > 512) {
      return;
    }

    const tokenCost = this.calculateTokenCost(message);

    if (!limiter.consume(tokenCost)) {
      client.socket.write('RATE_LIMITED\n');
      this.circuitBreaker.recordFailure();
      return;
    }

    client.msgCount++;
    this.messageBuffer.writeMessage(clientId, message);
    this.broadcastMessage(clientId, message);
    this.circuitBreaker.recordSuccess();
  }

  calculateTokenCost(message) {
    const baseTokens = 1;
    const lengthPenalty = Math.floor(message.length / 128);
    const healthScore = this.circuitBreaker.getHealthScore();
    const scaleFactor = Math.floor((100 - healthScore) / 25);
    return baseTokens + lengthPenalty + scaleFactor;
  }

  broadcastMessage(senderId, message) {
    const payload = `MSG ${senderId} ${message}\n`;
    for (const [id, client] of this.clients) {
      if (id !== senderId) {
        try {
          client.socket.write(payload);
        } catch (e) {
          this.handleDisconnect(id);
        }
      }
    }
  }

  handleDisconnect(clientId) {
    this.clients.delete(clientId);
    this.rateLimiters.delete(clientId);
  }
}

const server = new ChatServer(8080);
server.start();
